use conduit_ai::ModelSignature;
use conduit_plot::rust_binding::{NativeRustBinding,PreparedNativeFamily,PreparedNativeFamilyLimits,PreparedNativeRustBinding};
fn main(){let b=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();let l=PreparedNativeFamilyLimits{maximum_types:64,maximum_laws_per_type:256,maximum_input_bytes:262144,maximum_retained_bytes:128*1024*1024,maximum_preparation_peak_bytes:256*1024*1024,maximum_conversion_requested_bytes:1024*1024*1024};let mut f=PreparedNativeFamily::prepare(&[ModelSignature::PREPARED_DESCRIPTOR],l).unwrap();let value=f.decode::<ModelSignature>(&b).unwrap();let encoded=value.encode().unwrap();assert_eq!(encoded,b);println!("full archived model signature {} bytes admitted and reencoded exactly; family {:?}",b.len(),f.storage_receipt());}
